import{_ as a,o,c as s,a2 as n}from"./chunks/framework.C4u7U0Dw.js";const g=JSON.parse('{"title":"行业提示词模板库","description":"14 类行业与岗位的提示词模板，每类 5 条高频场景。抄骨架、换成你的、存下来——三分钟能上手。","frontmatter":{"title":"行业提示词模板库","description":"14 类行业与岗位的提示词模板，每类 5 条高频场景。抄骨架、换成你的、存下来——三分钟能上手。"},"headers":[],"relativePath":"community/prompts/index.md","filePath":"community/prompts/index.md"}'),r={name:"community/prompts/index.md"};function e(d,t,p,l,i,h){return o(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="🏭-行业提示词模板库" tabindex="-1">🏭 行业提示词模板库 <a class="header-anchor" href="#🏭-行业提示词模板库" aria-label="Permalink to &quot;🏭 行业提示词模板库&quot;">​</a></h1><blockquote><p>这是 OPC 社区的 🧰 资源库第一个大件。 规则只有一句：<strong>不做&quot;100 个万能提示词&quot;那种大礼包，只做你明天真的会用的那 5 条。</strong></p></blockquote><hr><h2 id="先说清楚-为什么这里按-行业-分" tabindex="-1">先说清楚：为什么这里按&quot;行业&quot;分 <a class="header-anchor" href="#先说清楚-为什么这里按-行业-分" aria-label="Permalink to &quot;先说清楚：为什么这里按&quot;行业&quot;分&quot;">​</a></h2><p>白皮书 <strong>附录 A 常用指令模板</strong> 讲的是&quot;怎么把话说清楚&quot;——那是<strong>通用能力</strong>。</p><p>但通用能力解决不了这个问题：</p><blockquote><p>我开水果店的，我该跟 AI 说什么？</p></blockquote><p>你不需要背 100 个提示词。你需要的是<strong>有人先把你这行的常见活儿列出来</strong>，你照着换几个字就能用。</p><p>所以这一库按行业分。每类 <strong>5 条</strong>，选的都是<strong>这行天天要干、又最烦</strong>的活。</p><hr><h2 id="🧱-所有行业共用一个骨架-先记这-3-句" tabindex="-1">🧱 所有行业共用一个骨架（先记这 3 句） <a class="header-anchor" href="#🧱-所有行业共用一个骨架-先记这-3-句" aria-label="Permalink to &quot;🧱 所有行业共用一个骨架（先记这 3 句）&quot;">​</a></h2><p>不管你干哪行，一条好用的提示词都是这三句：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 我是谁 + 我手上有什么（背景）</span></span>
<span class="line"><span>2. 给我什么（交付物：格式、数量、长度）</span></span>
<span class="line"><span>3. 按什么规矩来（标准、样例、禁止项）</span></span></code></pre></div><p>第 2 期周刊「<strong>把最常说的三句话写成提示词</strong>」讲的就是这个；第 1 期「<strong>三段式提示词骨架</strong>」是它的完整版。</p><p>后面每个行业的模板，都是这三句<strong>换成本行的说法</strong>。你会发现骨架长得一模一样——这就对了，说明你已经学会它了。</p><hr><h2 id="🔧-怎么用-三步-别跳过" tabindex="-1">🔧 怎么用（三步，别跳过） <a class="header-anchor" href="#🔧-怎么用-三步-别跳过" aria-label="Permalink to &quot;🔧 怎么用（三步，别跳过）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>步骤</th><th>做什么</th><th>花多久</th></tr></thead><tbody><tr><td><strong>1. 抄</strong></td><td>找到你这行，挑一条最像你现在要干的活的</td><td>1 分钟</td></tr><tr><td><strong>2. 换</strong></td><td>把 <code>【】</code> 里的内容换成你自己的真实信息（越具体越好）</td><td>2 分钟</td></tr><tr><td><strong>3. 存</strong></td><td>改好用一次、效果好的那条，存进你自己的&quot;常用三句话&quot;清单</td><td>30 秒</td></tr></tbody></table><blockquote><p><strong>第 3 步最重要。</strong> 抄 100 条不如存下来 3 条自己改过的。存下来的那 3 条，才是你的资产。</p></blockquote><hr><h2 id="📚-按行业找-14-类" tabindex="-1">📚 按行业找（14 类） <a class="header-anchor" href="#📚-按行业找-14-类" aria-label="Permalink to &quot;📚 按行业找（14 类）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>行业 / 岗位</th><th>这个里面有什么</th></tr></thead><tbody><tr><td>🧰 <strong><a href="/MoMAWork-/community/prompts/通用办公.html">通用办公（人人都能用）</a></strong></td><td>会议记录→纪要、难写的邮件、散文件→台账、一段话→表格、一页纸周报</td></tr><tr><td>🛒 <strong><a href="/MoMAWork-/community/prompts/电商与直播.html">电商与直播带货</a></strong></td><td>详情页文案、标题与关键词、差评与售后回复、直播讲品脚本、竞品对比</td></tr><tr><td>🍜 <strong><a href="/MoMAWork-/community/prompts/实体门店与餐饮.html">实体门店与餐饮</a></strong></td><td>菜名与描述、团购活动（含保本算法）、排班、投诉处理、私域群排期</td></tr><tr><td>🎓 <strong><a href="/MoMAWork-/community/prompts/教育培训.html">教育培训</a></strong></td><td>课程介绍、一节课教案、作业批改反馈、家长沟通、阶段学习报告</td></tr><tr><td>🏠 <strong><a href="/MoMAWork-/community/prompts/房产与中介.html">房产与中介</a></strong></td><td>房源描述、带看复盘、跟进节奏、小区对比表、谈判准备</td></tr><tr><td>💊 <strong><a href="/MoMAWork-/community/prompts/医疗健康.html">医疗健康与药店</a></strong></td><td>健康科普、患者沟通、用药提醒、随访记录整理、服务介绍（<strong>含红线</strong>）</td></tr><tr><td>⚖️ <strong><a href="/MoMAWork-/community/prompts/法律与财税.html">法律与财税</a></strong></td><td>合同初审要点、条款翻译、事项时间线、资料催收、内部制度（<strong>含边界</strong>）</td></tr><tr><td>📞 <strong><a href="/MoMAWork-/community/prompts/销售与客户跟进.html">销售与客户跟进</a></strong></td><td>客户作战地图、三档报价、跟进节奏、异议处理、丢单复盘</td></tr><tr><td>👥 <strong><a href="/MoMAWork-/community/prompts/人力资源与招聘.html">人力资源与招聘</a></strong></td><td>JD 撰写、简历初筛打分表、面试提纲、绩效面谈、制度文件</td></tr><tr><td>🎬 <strong><a href="/MoMAWork-/community/prompts/自媒体与内容创作.html">自媒体与内容创作</a></strong></td><td>选题库、3 分钟口播稿、一稿多平台改写、评论区回复、数据复盘</td></tr><tr><td>💻 <strong><a href="/MoMAWork-/community/prompts/技术与研发.html">技术与研发</a></strong></td><td>需求拆解、代码审查、报错排查、技术方案、写文档</td></tr><tr><td>🌏 <strong><a href="/MoMAWork-/community/prompts/外贸与跨境.html">外贸与跨境</a></strong></td><td>开发信、询盘回复、报价单、交期沟通、平台文案与合规</td></tr><tr><td>📋 <strong><a href="/MoMAWork-/community/prompts/行政与文秘.html">行政与文秘</a></strong></td><td>会议筹备清单、通知公告、接待方案、日程协调、汇报材料</td></tr><tr><td>🏭 <strong><a href="/MoMAWork-/community/prompts/制造与工厂.html">制造与工厂</a></strong></td><td>作业指导书、不良分析、设备点检表、安全培训、排产交期</td></tr></tbody></table><blockquote><p><strong>没找到你这行？</strong> 直接发我（微信，或 <code>1972597219@qq.com</code>），说一句&quot;我是干 XX 的，我最烦干 YY&quot;。 <strong>每月新增 4 个行业</strong>，点单的优先做。</p></blockquote><hr><h2 id="🚀-三个万能模板-今天就能用-不看行业" tabindex="-1">🚀 三个万能模板（今天就能用，不看行业） <a class="header-anchor" href="#🚀-三个万能模板-今天就能用-不看行业" aria-label="Permalink to &quot;🚀 三个万能模板（今天就能用，不看行业）&quot;">​</a></h2><h3 id="模板-1-·-「我一句话-你干活」标准骨架" tabindex="-1">模板 1 · 「我一句话，你干活」标准骨架 <a class="header-anchor" href="#模板-1-·-「我一句话-你干活」标准骨架" aria-label="Permalink to &quot;模板 1 · 「我一句话，你干活」标准骨架&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我是【做什么的 / 在什么场景】。</span></span>
<span class="line"><span>我要你产出一份【交付物名称】，格式是【表格 / 清单 / 300 字短文】。</span></span>
<span class="line"><span>标准：①【必须满足什么】②【禁止什么】③参考这份样例：【贴一个你满意的例子】。</span></span>
<span class="line"><span>不确定的地方先问我，别自己猜。</span></span></code></pre></div><h3 id="模板-2-·-「先给样例-再让它干」-第-2-期装备-002" tabindex="-1">模板 2 · 「先给样例，再让它干」（第 2 期装备 002） <a class="header-anchor" href="#模板-2-·-「先给样例-再让它干」-第-2-期装备-002" aria-label="Permalink to &quot;模板 2 · 「先给样例，再让它干」（第 2 期装备 002）&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>下面是一份我觉得写得好的样例：</span></span>
<span class="line"><span>【粘贴样例】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>现在按同样的风格和结构，帮我处理下面这份新内容：</span></span>
<span class="line"><span>【粘贴新内容】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：结构和详略程度跟样例一致，不要额外发挥。</span></span></code></pre></div><h3 id="模板-3-·-「别一次给我十版-先给我一版并说理由」" tabindex="-1">模板 3 · 「别一次给我十版，先给我一版并说理由」 <a class="header-anchor" href="#模板-3-·-「别一次给我十版-先给我一版并说理由」" aria-label="Permalink to &quot;模板 3 · 「别一次给我十版，先给我一版并说理由」&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我要做【这件事】。请只给我 1 个方案，并说明：</span></span>
<span class="line"><span>① 你为什么这么选 ② 这个方案的弱点是什么 ③ 如果换一个思路，你会换成什么。</span></span>
<span class="line"><span>我要能判断，不要一堆选项让我自己挑。</span></span></code></pre></div><hr><h2 id="⚠️-三条使用提醒-很重要" tabindex="-1">⚠️ 三条使用提醒（很重要） <a class="header-anchor" href="#⚠️-三条使用提醒-很重要" aria-label="Permalink to &quot;⚠️ 三条使用提醒（很重要）&quot;">​</a></h2><ol><li><strong>模板是起点，不是标准答案。</strong> 每个行业的真实情况都不一样，<code>【】</code> 里的东西必须换成你自己的。原样发出去，结果一定很平庸。</li><li><strong>涉及法律、医疗、财税、投资的内容，AI 的输出只能当&quot;草稿和提醒&quot;，不能当专业意见。</strong> 真要用，请找专业人士过一遍。这几个行业的页面里我都标了红线，请务必看。</li><li><strong>不要往提示词里粘贴不该给出去的隐私数据</strong>（身份证号、完整病历、客户完整手机号、公司未公开财务）。要处理就先用 XX 脱敏。</li></ol><hr><h2 id="🕒-更新记录" tabindex="-1">🕒 更新记录 <a class="header-anchor" href="#🕒-更新记录" aria-label="Permalink to &quot;🕒 更新记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>日期</th><th>更新了什么</th></tr></thead><tbody><tr><td>2026-09-16</td><td>首次上线：<strong>14 类行业与岗位，每类 5 条，共 70 条</strong>模板（含通用办公）</td></tr></tbody></table><blockquote><p>这一库会跟着社区周刊一起长。每次新增行业，我都会在 <strong><a href="/MoMAWork-/community/weekly/">社区周刊</a></strong> 的周三「装备补给」里说一声。</p></blockquote><hr><p><strong>想点单 / 想贡献一条你自己改得特别好的模板</strong>：<code>1972597219@qq.com</code>（或扫码加我微信，见 <a href="/MoMAWork-/community/">社区首页</a>）</p>`,40)])])}const m=a(r,[["render",e]]);export{g as __pageData,m as default};
